    $ui = \App\Support\Ui::class;
    $airportsByCode = $airports->keyBy('code');
    $query = collect($filters)->except('page')->filter(fn($value)=>$value!==null && $value!=='' && $value!==[])->all();
    $url = fn($changes)=>'/?'.http_build_query(array_merge($query, $changes));
    $clearQuery = array_intersect_key($query, array_flip(['origin','destination','date','passenger_count','trip_type','return_date','outbound']));
    $clearUrl = '/'.($clearQuery ? '?'.http_build_query($clearQuery) : '');
    $rangeKeys=['price_min','price_max','duration_min','duration_max','layover_min','layover_max'];
    $active = collect($query)->except(['origin','destination','date','passenger_count','sort','trip_type','return_date','outbound',...$rangeKeys])->reject(fn($value,$key)=>$key==='available_only' && !$value)->sum(fn($value)=>is_array($value) ? count($value) : 1);
    foreach(['price','duration','layover'] as $rangeKey) { if(isset($query[$rangeKey.'_min']) || isset($query[$rangeKey.'_max'])) $active++; }
@endphp
